<?php defined( 'ABSPATH' ) || exit; ?>
<div class="wrap"><h1><?php esc_html_e( 'Cyberfort AI Register', 'cyberfort-ai-register' ); ?></h1><?php settings_errors( 'cfair_settings' ); ?><form method="post" action="options.php"><?php settings_fields( 'cfair_settings' ); ?><table class="form-table"><tr><th><label for="cfair_server_url"><?php esc_html_e( 'AI Register server address', 'cyberfort-ai-register' ); ?></label></th><td><input class="regular-text" type="url" id="cfair_server_url" name="cfair_server_url" value="<?php echo esc_attr( get_option( 'cfair_server_url' ) ); ?>" placeholder="https://airegister.cyberfort.lv"></td></tr><tr><th><?php esc_html_e( 'Connector API key', 'cyberfort-ai-register' ); ?></th><td><input class="regular-text" type="password" name="cfair_api_key" value="" placeholder="<?php echo esc_attr( cfair_mask_key( (string) get_option( 'cfair_api_key' ) ) ); ?>"><p class="description"><?php esc_html_e( 'Leave blank to keep the current key. WordPress administrators can access this connector credential; it does not grant access to confidential records.', 'cyberfort-ai-register' ); ?></p></td></tr><tr><th><?php esc_html_e( 'Environment', 'cyberfort-ai-register' ); ?></th><td><select name="cfair_environment"><?php foreach ( [ 'production', 'staging', 'development' ] as $value ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( get_option( 'cfair_environment' ), $value ); ?>><?php echo esc_html( ucfirst( $value ) ); ?></option><?php endforeach; ?></select></td></tr><tr><th><?php esc_html_e( 'Default language', 'cyberfort-ai-register' ); ?></th><td><select name="cfair_language"><?php foreach ( [ 'auto', 'lv', 'en' ] as $value ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( get_option( 'cfair_language' ), $value ); ?>><?php echo esc_html( strtoupper( $value ) ); ?></option><?php endforeach; ?></select></td></tr><tr><th><?php esc_html_e( 'Cache duration', 'cyberfort-ai-register' ); ?></th><td><select name="cfair_cache_duration"><?php foreach ( [ 300 => '5 minutes', 900 => '15 minutes', 1800 => '30 minutes', 3600 => '1 hour', 21600 => '6 hours' ] as $value => $label ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( (int) get_option( 'cfair_cache_duration' ), $value ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></td></tr></table><?php submit_button(); ?></form><p><button class="button" id="cfair-test"><?php esc_html_e( 'Test connection', 'cyberfort-ai-register' ); ?></button> <span id="cfair-test-result"></span></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="cfair_clear_cache"><?php wp_nonce_field( 'cfair_clear_cache' ); ?><button class="button"><?php esc_html_e( 'Clear cache', 'cyberfort-ai-register' ); ?></button></form></div><script>document.getElementById('cfair-test').onclick=function(e){e.preventDefault();fetch(ajaxurl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'action=cfair_test_connection&_ajax_nonce=<?php echo esc_js( wp_create_nonce( 'cfair_test_connection' ) ); ?>'}).then(r=>r.json()).then(r=>document.getElementById('cfair-test-result').textContent=r.success?'Connection successful':'Connection failed: '+r.data.message)}</script>
